import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`dcf-valuation`,heroTitle:`Value any stock in minutes`,heroSubtitle:`Perplexity Computer pulls financials, projects free cash flow across three scenarios, and delivers a complete DCF valuation — automatically.`,inputUrlCta:`Value this stock`,inputUrlPlaceholder:`e.g. NVDA`,inputUrlPrefill:`Go to {url} and identify the stock ticker or company. Then build a complete DCF valuation model. (1) Pull 5 years of historical financials — revenue, EBITDA, capex, working capital, and free cash flow. (2) Project free cash flow for the next 5 years under bear, base, and bull assumptions, clearly stating growth rates, margin assumptions, and reinvestment rates for each scenario. (3) Calculate WACC using the company's capital structure, beta, risk-free rate, and equity risk premium. (4) Apply a DCF model with terminal value using a perpetuity growth method, and discount all cash flows back to present value. (5) Build a sensitivity table showing implied share price across a range of WACC and terminal growth rate assumptions. (6) Calculate implied upside or downside versus the current share price for each scenario. (7) Deliver a one-page investment summary with the company overview, key assumptions, valuation range, implied upside, and a clear bull/base/bear recommendation — formatted for presentation to an investment committee.`,heroOverlaySteps:[`Pulling 5 years of historical financials and free cash flow`,`Projecting cash flows under bear, base, and bull scenarios`,`Running DCF model with WACC and terminal value calculations`,`Building sensitivity tables and investment summary — ready to review`],generatingSteps:[`Looking up {url} to pull historical financials and company data`,`Designing an agent to project free cash flow and run three-scenario DCF analysis`,`Configuring WACC calculation, sensitivity tables, and implied upside logic`,`Setting up the one-page investment summary and valuation output`],featureSectionTitle:`From ticker to investment thesis`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can pitch`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Slack — Computer exports your valuation models and summaries straight into the tools your team already uses.`,`5-year projections. Sensitivity tables. Implied upside by scenario. One-page investment summary. Computer delivers a complete valuation package ready for committee review.`],capabilitySectionTitle:`Your equity analyst, on autopilot`,capabilitySectionSubtitle:`Enter a ticker, step away, get a complete DCF valuation.`,capabilityCards:[{title:`Financial Data Pull`,description:`Computer can pull 5 years of revenue, EBITDA, capex, working capital, and free cash flow — organized and ready for modeling.`},{title:`Scenario Projections`,description:`Computer can project free cash flow under bear, base, and bull assumptions — with explicit growth rates, margins, and reinvestment rates for each case.`},{title:`DCF & Sensitivity`,description:`Computer can calculate WACC, apply terminal value, discount cash flows, and build sensitivity tables across discount rate and growth rate ranges.`},{title:`Connect Your Tools`,description:`Computer can export to Google Sheets, Google Drive, Notion, and Slack — build workflows across your research and portfolio operations.`},{title:`Knows Your Models`,description:`Computer can remember your preferred assumptions, discount rates, and valuation frameworks across sessions — so every new analysis starts from your playbook.`},{title:`Price & Filing Alerts`,description:`Computer can monitor earnings releases and price movements — and alert you when a stock's implied upside changes materially from your last valuation.`}]});export{t as default};
